-- #161: NEVO-online 2025/9.0 as the nutrition source for
-- reference.ingredients -- replaces the 13-row hand-curated seed from
-- 20260730000001_ingredient_library.sql with the full 2328-row NEVO food
-- list, adds fibre + a bilingual category pair, and records per-row
-- nutrient basis (per 100g vs. per 100ml).
-- Implements ADR-0013 (docs/decisions/0013-nevo-nutrition-import.md), which
-- amends ADR-0011 §5's NEVO prohibition; everything else in ADR-0011
-- (reference schema rules §1, two-layer ingredient library §2, user-first
-- mass resolution §3, NULL never meaning 0 §4, extended RLS gate §6) is
-- unchanged and this migration does not touch it. ADR-0013 is binding; this
-- migration only executes it.
--
-- Conventions per Architecture §4.1 / ADR-0001 / ADR-0009, same house style
-- as 20260720000001_profiles.sql / 20260730000001_ingredient_library.sql.
--
-- NEVO attribution (ADR-0013 §2, mandatory even in this schema-layer
-- migration's comments): "Based on data from NEVO online version 2025/9.0,
-- RIVM, Bilthoven and other data sources." The UI-facing rendering of this
-- string is a separate ticket (the four macro dropdowns on the recipe
-- detail page); this migration's obligation is the `source`/`source_ref`/
-- `source_version` columns on every seeded row below.
--
-- Row data is generated by scripts/import-nevo.ts (ADR-0013 §5) reading the
-- git-ignored upstream CSV (NEVO2025_v9.0/NEVO2025_v9.0.csv, 108 MB of raw
-- RIVM exports, never committed -- see .gitignore) and printing the exact
-- `insert into reference.ingredients (...) values (...)` statement pasted
-- verbatim below. Re-running the script against a future NEVO version
-- regenerates this block; nothing here is hand-edited.

-- ============================================================================
-- Schema change: reference.ingredients gains fibre, nutrient_basis and a
-- bilingual category pair, and loses the old single `category` column.
-- ============================================================================

-- Grepped the whole repo (app/, components/, lib/) for `.category` /
-- `reference.ingredients` usage before dropping the column (per the ticket's
-- explicit instruction). Findings:
--  - Every `.category` hit outside this table is `recipe_categories`
--    (`RecipeCategoryRow`/`CategoryWithRecipes` in lib/recipes/queries.ts,
--    CategoryPanel.tsx, ReceptenBoard.tsx, RecipePanel.tsx) or
--    `public.ingredients.category` (IngredientRow, e.g.
--    IngredientSearchPanel.stories.tsx's `mockOwnIngredients`) -- an
--    entirely different table this migration does not touch.
--  - The one real hit: `components/organisms/IngredientSearchPanel.
--    stories.tsx`'s `mockReferenceIngredients` fixture is typed as
--    `ReferenceIngredientRow[]` and set `category: null` on each entry.
--    Updated in the same PR to `category_nl: null, category_en: null` so
--    the story file still type-checks against the new Row shape.
--  - No server code, query, or component reads
--    `reference.ingredients.category` today (ADR-0011 §4 already left every
--    nutrient column NULL and nothing in the UI surfaced category at all
--    yet) -- the drop below is safe.

alter table reference.ingredients
  add column fiber_g_per_100g numeric,
  add column category_nl text,
  add column category_en text;

-- nutrient_basis is `not null`, so it can't simply be added with no default
-- against the 13 existing rows -- but those 13 rows are deleted by this same
-- migration (below) before any query can observe a default-less row, so no
-- default is ever left behind for real data to rely on. Sequence: add the
-- column nullable, delete the old seed, backfill nothing (nothing left to
-- backfill), then tighten to not null before the NEVO insert populates it.
alter table reference.ingredients
  add column nutrient_basis text;

delete from reference.ingredients;

alter table reference.ingredients
  alter column nutrient_basis set not null;

alter table reference.ingredients
  add constraint ingredients_nutrient_basis_check
    check (nutrient_basis in ('per_100g', 'per_100ml'));

alter table reference.ingredients
  drop column category;

comment on table reference.ingredients is
  'Canonical ingredient library, seeded from NEVO-online 2025/9.0 (ADR-0013, '
  'amending ADR-0011 §2/§5). No user_id: shared reference data, immutable '
  'outside migrations. kcal/protein/carbs/fat/fiber are nullable and NULL '
  'must never be treated as 0 (ADR-0011 §4). nutrient_basis records whether '
  'a row''s five nutrient columns are per 100g or per 100ml (ADR-0013 §4) -- '
  'the read layer must treat a per_100ml row''s nutrients as unknown rather '
  'than feeding them into per-100g math.';

comment on column reference.ingredients.category_nl is
  'NEVO''s "Voedingsmiddelgroep" (Dutch food group), verbatim (ADR-0013 §6).';

comment on column reference.ingredients.category_en is
  'NEVO''s "Food group" (English food group), verbatim (ADR-0013 §6).';

comment on column reference.ingredients.fiber_g_per_100g is
  'NEVO''s "FIBT (g)" (dietary fibre). Nullable -- empty in the source means '
  'unknown, never 0 (ADR-0011 §4); 7 of NEVO 2025/9.0''s 2328 rows are '
  'empty here. Displayed since #166, which added Figma''s fibre button '
  '(4025:11826) to the NutritionalData row (3997:15948 mobile / '
  '3997:15543 desktop); its dropdown carries ADR-0013 §2''s mandatory NEVO '
  'attribution line, like the other four macros (ADR-0013 §3).';

comment on column reference.ingredients.nutrient_basis is
  'Whether this row''s kcal/protein/carbs/fat/fiber columns are per 100g or '
  'per 100ml (ADR-0013 §4). NEVO''s 53 "Flesvoeding en preparaten" (infant '
  'formula) rows are per_100ml; the other 2275 are per_100g. A per_100ml '
  'row''s nutrients must be read as unknown by per-100g math, never mixed '
  'in directly.';

-- ============================================================================
-- Seed replacement: delete the 13 hand-curated rows (already gone -- the
-- unconditional `delete from reference.ingredients` above, run before
-- nutrient_basis could be made not null, already cleared the table), then
-- insert the full 2328-row NEVO-online 2025/9.0 extract.
--
-- public.ingredients.reference_id is `on delete set null` (ADR-0011 §2), so
-- any pre-existing user row that pointed at one of the 13 deleted
-- hand-curated rows is detached, not destroyed: it keeps its own `name` and
-- stays fully renderable, unlinked from the shared layer exactly as
-- ADR-0011 §2 requires. reference.ingredient_unit_masses had no rows
-- referencing the deleted ids either (that table is seeded by nothing yet,
-- per 20260730000001_ingredient_library.sql), so the cascade is a no-op in
-- practice today.
--
-- Generated verbatim by scripts/import-nevo.ts against
-- NEVO2025_v9.0/NEVO2025_v9.0.csv -- 2328 rows, ordered by NEVO-code
-- ascending (deterministic, ADR-0013 §5). Do not hand-edit; re-run the
-- script and re-paste instead.
-- ============================================================================

